import json

import pytest
import python_rule

UV_EXPORT = "# This file was autogenerated by uv via the following command:\n"


def errors(capsys) -> list[str]:
    return [line for line in capsys.readouterr().out.splitlines() if line.startswith("::error")]


def run(monkeypatch, pyprojects=(), importlinters=()) -> int:
    monkeypatch.setenv("PYPROJECTS", json.dumps(list(pyprojects)))
    monkeypatch.setenv("IMPORTLINTERS", json.dumps(list(importlinters)))
    with pytest.raises(SystemExit) as exit_info:
        python_rule.main()
    return exit_info.value.code


def test_legacy_files(repo, monkeypatch, capsys):
    repo(
        {
            "app/pyproject.toml": "",
            "app/requirements.txt": "requests\n",  # pyproject.toml の隣にある
            "app/requirements/dev.txt": "pytest\n",  # requirements/ の親に pyproject.toml がある
            "app/requirements-lock.txt": UV_EXPORT,  # uv export で書き出したもの
            "docs/requirements.txt": "mkdocs\n",  # pyproject.toml の隣ではない
            "setup.py": "setup(install_requires=['x'])\n",
            "native/setup.py": "setup(ext_modules=[])\n",  # 依存を宣言しない
            "tools/Pipfile": "",
        }
    )
    assert run(monkeypatch) == 1
    assert [line.split("::")[1] for line in errors(capsys)] == [
        "error file=app/requirements.txt",
        "error file=app/requirements/dev.txt",
        "error file=setup.py",
        "error file=tools/Pipfile",
    ]


def test_requirements_without_pyproject(repo, monkeypatch, capsys):
    # pyproject.toml が無い repo では、Python のコードがあるときだけ requirements を対象にする
    repo({"requirements.txt": "requests\n"})
    assert run(monkeypatch) == 0
    repo({"main.py": ""})
    assert run(monkeypatch) == 1
    assert errors(capsys) == [
        (
            "::error file=requirements.txt::requirements.txt ではなく pyproject.toml と uv.lock で依存を管理してください"
            "（https://docs.astral.sh/uv/guides/migration/pip-to-project/）"
        )
    ]


def test_lock(repo, monkeypatch, capsys):
    repo({"uv.lock": 'source = { editable = "packages/a" }\n'})
    pyprojects = [
        {"path": "pyproject.toml", "project": ".", "rel": "."},
        {"path": "packages/a/pyproject.toml", "project": ".", "rel": "packages/a"},
        {"path": "packages/b/pyproject.toml", "project": ".", "rel": "packages/b"},
        {"path": "other/pyproject.toml", "project": "", "rel": "other"},
    ]
    importlinters = [
        {"path": "pyproject.toml", "project": ".", "rel": "."},
        {"path": "other/.importlinter", "project": "", "rel": "other"},
    ]
    assert run(monkeypatch, pyprojects, importlinters) == 1
    assert [line.split("::")[1] for line in errors(capsys)] == [
        "error file=packages/b/pyproject.toml",
        "error file=other/pyproject.toml",
        "error file=other/.importlinter",
    ]


def test_escape_file_property(repo, monkeypatch, capsys):
    repo({"a,b:c/Pipfile": ""})
    assert run(monkeypatch) == 1
    assert errors(capsys)[0].startswith("::error file=a%2Cb%3Ac/Pipfile::a,b:c/Pipfile ではなく")
